class Solution {
    public int minimumOperations(String num) {
        int n = num.length();
        int ans = num.indexOf('0') != -1 ? n - 1 : n;
        String[] targets = {"00", "25", "50", "75"};
        for (String t : targets) {
            int j = n - 1;
            while (j >= 0 && num.charAt(j) != t.charAt(1)) j--;
            if (j < 0) continue;
            int i = j - 1;
            while (i >= 0 && num.charAt(i) != t.charAt(0)) i--;
            if (i >= 0) {
                int deletions = (n - 1 - j) + (j - 1 - i);
                ans = Math.min(ans, deletions);
            }
        }
        return ans;
    }
}

