var minimumOperations = function(num) {
    const n = num.length;
    let ans = num.includes('0') ? n - 1 : n;
    const targets = ["00", "25", "50", "75"];
    for (const t of targets) {
        let j = n - 1;
        while (j >= 0 && num[j] !== t[1]) j--;
        if (j < 0) continue;
        let i = j - 1;
        while (i >= 0 && num[i] !== t[0]) i--;
        if (i >= 0) {
            const deletions = (n - 1 - j) + (j - 1 - i);
            if (deletions < ans) ans = deletions;
        }
    }
    return ans;
};
